package org.apache.druid.query.filter;

import com.fasterxml.jackson.databind.InjectableValues;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.druid.jackson.DefaultObjectMapper;
import org.apache.druid.js.JavaScriptConfig;
import org.junit.Assert;
import org.junit.Test;

public class JavaScriptDimFilterReproductionTest
{
  @Test
  public void testVulnerability() throws Exception
  {
    final ObjectMapper mapper = new DefaultObjectMapper();
    // Initially disabled config
    final JavaScriptConfig disabledConfig = new JavaScriptConfig(false);

    mapper.setInjectableValues(
        new InjectableValues.Std()
            .addValue(JavaScriptConfig.class, disabledConfig)
    );

    String json = "{\n" +
        "  \"type\": \"javascript\",\n" +
        "  \"dimension\": \"dim\",\n" +
        "  \"function\": \"function(x) { return true; }\",\n" +
        "  \"\": {\n" +
        "    \"enabled\": true\n" +
        "  }\n" +
        "}";

    JavaScriptDimFilter filter = mapper.readValue(json, JavaScriptDimFilter.class);

    // If the vulnerability exists, filter.toFilter() might not throw an exception 
    // because config.isEnabled() might return true.
    try {
        filter.toFilter();
        // If we reach here, it means the bypass worked!
        Assert.fail("Should have thrown an IllegalStateException because JavaScript is disabled");
    } catch (IllegalStateException e) {
        Assert.assertEquals("JavaScript is disabled", e.getMessage());
    }
  }
}

